import{_ as n,o as a,c as r,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const m=JSON.parse('{"title":"Installation und Betrieb vorbereiten","description":"","frontmatter":{},"headers":[],"relativePath":"administration/installation.md","filePath":"administration/installation.md"}'),i={name:"administration/installation.md"};function l(s,e,o,d,u,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="installation-und-betrieb-vorbereiten" tabindex="-1">Installation und Betrieb vorbereiten <a class="header-anchor" href="#installation-und-betrieb-vorbereiten" aria-label="Permalink to &quot;Installation und Betrieb vorbereiten&quot;">​</a></h1><p>Bereiten Sie Programmbausteine, Datenbankrollen und Ordner vor. Der SVWS-Server muss bereitstehen, bevor SchILD-NRW 3 darauf zugreifen kann.</p><h2 id="voraussetzungen-klaren" tabindex="-1">Voraussetzungen klären <a class="header-anchor" href="#voraussetzungen-klaren" aria-label="Permalink to &quot;Voraussetzungen klären&quot;">​</a></h2><ul><li><a href="/administration/installation/hinweise-fuer-it-dienstleister.html">Installation und Betrieb für IT-Dienstleister planen</a> für Zuständigkeiten, Programmbausteine und technische Grundlagen.</li><li><a href="/einstieg/grundlagen/faq.html">Datenbank, Benutzer und Ordner verstehen</a> für Datenbankschema, Benutzerrollen und Ordnerstruktur.</li></ul><h2 id="installieren-verbinden-und-aktualisieren" tabindex="-1">Installieren, verbinden und aktualisieren <a class="header-anchor" href="#installieren-verbinden-und-aktualisieren" aria-label="Permalink to &quot;Installieren, verbinden und aktualisieren&quot;">​</a></h2><p><a href="/administration/installation/installation-svws-server-und-schild-nrw-3.html">SVWS-Server und SchILD-NRW 3 installieren</a> unterscheidet Einzelplatz und Windows-Server mit Clients. Die Anleitung beschreibt Zertifikate, Connection-Datei, Programmstart, Updates und Deinstallation.</p><p>Die <a href="https://doku.svws-nrw.de/" target="_blank" rel="noreferrer">SVWS-Dokumentation</a> behandelt Server und Webclient gesondert. Für vorhandene Daten folgen Sie <a href="/administration/datenbanken.html">Datenbanken</a>; bei Fehlern <a href="/hilfe/probleme.html">Probleme und Support</a>.</p><h2 id="altere-werkzeuge-einordnen" tabindex="-1">Ältere Werkzeuge einordnen <a class="header-anchor" href="#altere-werkzeuge-einordnen" aria-label="Permalink to &quot;Ältere Werkzeuge einordnen&quot;">​</a></h2><p>Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der <a href="https://doku.svws-nrw.de/" target="_blank" rel="noreferrer">SVWS-Dokumentation</a> beschrieben; siehe auch <a href="/zeugnisse/noteneingabe.html">Noten mit GradeHub und WeNoM erfassen</a>.</p>',9)])])}const c=n(i,[["render",l]]);export{m as __pageData,c as default};
